import { useState, useEffect } from "react";

function App() {
    const [data, setData] = useState([]);

    useEffect(() => {
        fetch("https://jsonplaceholder.typicode.com/posts")
            .then(res => res.json())
            .then(result => setData(result));
    }, []);

    return (
        <div>
            <h1>Posts</h1>

            {data.map((item) => (
                <div key={item.id}>
                    <h3>{item.title}</h3>
                    <p>{item.body}</p>
                </div>
            ))}
        </div>
    );
}

export default App;
